\title{Structural Reductions for Beal's Conjecture:\\Primitive Solutions, Fermat--Catalan Signatures, and Powered Additive Triples}
\author{Aristotle}
\date{July 25, 2026}

\begin{document}
\maketitle

\begin{abstract}
Beal's conjecture asserts that positive integer solutions of $A^x+B^y=C^z$ with $x,y,z>2$ have a common prime divisor of the bases $A,B,C$. The conjecture remains open. We identify its exact primitive core and connect that core to two broader Diophantine frameworks. A prime dividing any two bases is shown to divide the third; consequently, absence of a common prime is equivalent to pairwise coprimality, and Beal's conjecture is equivalent to nonexistence of primitive solutions. Every allowed exponent triple satisfies $1/x+1/y+1/z\leq1$, giving a precise conditional implication from primitive Fermat--Catalan exclusion. Every primitive candidate also maps canonically to the coprime additive triple $(A^x,B^y,C^z)$, isolating the powered-triple consequence of the $abc$ conjecture that would suffice. If two bases are Fibonacci numbers $F_m,F_n$, strong divisibility forces $F_{\gcd(m,n)}=1$, hence $\gcd(m,n)\in\{1,2\}$. We also give bounded-search and screening algorithms. A search over bases at most $40$ and exponents from $3$ through $6$ finds $23$ ordered solutions, all nonprimitive; this is finite evidence only.
\end{abstract}

\section{Introduction}
Consider
\begin{equation}\label{eq:beal}
 A^x+B^y=C^z
\end{equation}
in positive integers. Beal's conjecture concerns $x,y,z>2$ and predicts a prime $p$ such that $p\mid A$, $p\mid B$, and $p\mid C$. Distinct exponents permit examples such as
\[
2^3+2^3=2^4,\qquad 7^3+7^4=14^3,\qquad 3^6+18^3=9^4.
\]
Their bases share the primes $2$, $7$, and $3$, respectively.

This paper does not claim a resolution of the open conjecture. It separates the unresolved exclusion from unconditional arithmetic reductions. The fundamental observation is that the equation propagates a prime from any pair of bases to the third. Thus ``no common prime'' becomes equivalent to three simultaneous coprimality conditions. The primitive candidate then belongs automatically to the Fermat--Catalan signature region and supplies a coprime additive triple suitable for $abc$ considerations. A Fibonacci specialization illustrates how extra structure in the bases yields further restrictions.

\section{Definitions}
\begin{definition}
A \emph{Beal solution} is a sextuple $(A,B,C,x,y,z)$ of positive integers satisfying \eqref{eq:beal} and $x,y,z>2$. Its bases \emph{have a common prime} if some prime divides all of $A,B,C$. It is \emph{primitive} if
\[
\gcd(A,B)=\gcd(A,C)=\gcd(B,C)=1.
\]
Beal's conjecture states that every Beal solution has a common prime.
\end{definition}

\begin{definition}
The \emph{signature} is $(x,y,z)$ and its reciprocal weight is
\[
\sigma(x,y,z)=\frac1x+\frac1y+\frac1z.
\]
It is a \emph{Fermat--Catalan signature} when $\sigma(x,y,z)\leq1$.
\end{definition}

\begin{definition}
An \emph{additive coprime triple} is a positive triple $(a,b,c)$ with $a+b=c$ and $\gcd(a,b)=1$. For $n>0$, its radical is
\[
\rad(n)=\prod_{p\mid n}p,
\]
the product over distinct prime divisors.
\end{definition}
Positive powers preserve prime support, so $\rad(U^n)=\rad(U)$ for $n>0$. We also use the elementary consequence of unique factorization that a prime dividing $U^n$, with $n>0$, divides $U$.

\section{Prime propagation and primitive reduction}
\begin{theorem}[Prime-Propagation Theorem]\label{thm:prop}
Let $A,B,C,x,y,z$ be positive integers satisfying \eqref{eq:beal}. If a prime $p$ divides any two of $A,B,C$, then it divides the third.
\end{theorem}
\begin{proof}
If $p\mid A$ and $p\mid B$, then $p\mid A^x+B^y=C^z$, whence $p\mid C$. If $p\mid A,C$, then $p$ divides $B^y=C^z-A^x$, whence $p\mid B$. The remaining case is symmetric.
\end{proof}

\begin{corollary}[Prime-support pattern]
For any prime in a positive-exponent solution, the number of bases among $A,B,C$ divisible by it is $0$, $1$, or $3$, never $2$.
\end{corollary}
\begin{proof}
Divisibility of exactly two bases contradicts Theorem~\ref{thm:prop}.
\end{proof}

\begin{theorem}[Primitive Reduction Theorem]\label{thm:primitive}
For a positive-exponent solution of \eqref{eq:beal}, the following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item no prime divides all three bases;
\item the bases are pairwise coprime.
\end{enumerate}
\end{theorem}
\begin{proof}
Condition (ii) plainly implies (i). Conversely, assume (i). If $\gcd(A,B)>1$, choose a prime divisor $p$ of this gcd. Then $p\mid A,B$, and Theorem~\ref{thm:prop} gives $p\mid C$, contradicting (i). Hence $\gcd(A,B)=1$. The same argument applied to $(A,C)$ and $(B,C)$ proves pairwise coprimality.
\end{proof}

\begin{theorem}[Primitive Form of Beal's Conjecture]\label{thm:equiv}
Beal's conjecture is equivalent to nonexistence of a primitive positive solution of \eqref{eq:beal} with $x,y,z>2$.
\end{theorem}
\begin{proof}
If Beal's conjecture holds, a primitive solution is impossible by Theorem~\ref{thm:primitive}. Conversely, a Beal solution without a common prime would be primitive by that theorem, contradicting nonexistence.
\end{proof}

\begin{remark}
Theorems~\ref{thm:prop} and \ref{thm:primitive} require only positive exponents. The threshold greater than $2$ belongs to Beal's conjecture rather than to prime propagation.
\end{remark}

\section{The Fermat--Catalan bridge}
\begin{theorem}[Signature Inclusion Theorem]\label{thm:sig}
Every Beal solution satisfies
\[
\frac1x+\frac1y+\frac1z\leq1.
\]
\end{theorem}
\begin{proof}
The integral inequalities $x,y,z>2$ imply $x,y,z\geq3$. Each reciprocal is at most $1/3$, and summation proves the claim.
\end{proof}
The boundary signature is $(3,3,3)$. Increasing any exponent moves the reciprocal weight below the boundary.

\begin{theorem}[Conditional Fermat--Catalan Implication]\label{thm:fc}
Assume that every positive solution of \eqref{eq:beal} with $x,y,z>2$ and $1/x+1/y+1/z\leq1$ fails to be primitive. Then Beal's conjecture holds.
\end{theorem}
\begin{proof}
A failure of Beal would yield a primitive solution by Theorem~\ref{thm:equiv}; Theorem~\ref{thm:sig} would put its signature in the assumed exclusion region, a contradiction.
\end{proof}
The premise is explicit and is not claimed here. The theorem records exactly which primitive Fermat--Catalan exclusion would be sufficient.

Exponent divisibility supplies an additional organization of signatures. If $x=kr$, then $A^x=(A^k)^r$, allowing signatures to be compared after changing a base. This motivates descent toward minimal signatures, but no finite descent theorem is asserted.

\section{The powered additive-triple bridge}
\begin{theorem}[Canonical Powered-Triple Theorem]\label{thm:abc}
Let $(A,B,C,x,y,z)$ be a primitive Beal solution and put
\[
a=A^x,\qquad b=B^y,\qquad c=C^z.
\]
Then $(a,b,c)$ is an additive coprime triple. Its coordinates are precisely the powered terms of \eqref{eq:beal}.
\end{theorem}
\begin{proof}
Positivity is immediate and \eqref{eq:beal} gives $a+b=c$. Since $\gcd(A,B)=1$, positive powers remain coprime, so $\gcd(A^x,B^y)=1$.
\end{proof}
The additive equation further gives $\gcd(a,c)=\gcd(b,c)=1$.

\begin{corollary}[Radical identity]\label{cor:rad}
For the powered triple of Theorem~\ref{thm:abc},
\[
\rad(abc)=\rad(ABC).
\]
Moreover,
\[
\rad(ABC)=\rad(A)\rad(B)\rad(C).
\]
\end{corollary}
\begin{proof}
Positive powers do not change the set of prime divisors, proving the first identity. Primitivity makes the three base prime supports disjoint, proving the second.
\end{proof}

\begin{theorem}[Conditional Powered-$abc$ Implication]\label{thm:abccond}
Assume no positive pairwise-coprime bases $A,B,C$ with $x,y,z>2$ can satisfy \eqref{eq:beal} as a coprime additive triple of powered terms. Then Beal's conjecture holds.
\end{theorem}
\begin{proof}
A failure of Beal would give a primitive solution by Theorem~\ref{thm:equiv}, and Theorem~\ref{thm:abc} would produce exactly the forbidden powered triple.
\end{proof}
This is the specialized consequence one would seek from an effective $abc$ principle; its premise is not asserted as an established theorem. Powers are relevant because $A^x$ grows at least cubically while its radical is bounded by $A$. In a primitive candidate the supports do not overlap, so radical estimates separate componentwise.

\section{Fibonacci specialization}
Let $F_0=0$, $F_1=1$, and $F_{n+2}=F_{n+1}+F_n$. The strong divisibility identity is
\begin{equation}\label{eq:fibgcd}
\gcd(F_m,F_n)=F_{\gcd(m,n)}.
\end{equation}

\begin{theorem}[Fibonacci Index Constraint]\label{thm:fib}
Suppose a primitive Beal solution has $A=F_m$ and $B=F_n$. Then
\[
F_{\gcd(m,n)}=1.
\]
\end{theorem}
\begin{proof}
Primitivity gives $\gcd(A,B)=1$. Substitute the Fibonacci bases and use \eqref{eq:fibgcd}.
\end{proof}

\begin{corollary}[Index-gcd classification]
Under the hypotheses of Theorem~\ref{thm:fib},
\[
\gcd(m,n)\in\{1,2\}.
\]
\end{corollary}
\begin{proof}
Under the stated indexing, $F_k=1$ precisely for $k=1,2$.
\end{proof}
This necessary condition turns coprimality of large Fibonacci values into a small index restriction. It does not itself exclude all such candidates; modular periodicity is a natural next ingredient.

\section{Algorithms and numerical exploration}
Fix a base bound $M$ and an exponent interval with $E$ exponents. Precompute a reverse table mapping each power $C^z$ to all pairs $(C,z)$ producing it. Then enumerate $(A,x)$ and $(B,y)$, form $S=A^x+B^y$, and retrieve all entries under key $S$. This uses $O(ME)$ stored entries and $O(M^2E^2)$ additions and expected constant-time table lookups, apart from output and arbitrary-precision bit costs. It avoids a further factor $ME$ from scanning every right-hand power.

For each hit compute
\[
d_{AB}=\gcd(A,B),\quad d_{AC}=\gcd(A,C),\quad d_{BC}=\gcd(B,C),\quad d=\gcd(A,B,C).
\]
It is primitive exactly when the first three gcds equal $1$, and it has a common prime exactly when $d>1$. Theorem~\ref{thm:primitive} says these classifications are complementary for an exact solution; disagreement detects a computational error.

Signature screening should use exact rational arithmetic for
\[
\sigma=\frac1x+\frac1y+\frac1z,
\]
avoiding floating-point ambiguity at $\sigma=1$. Fibonacci screening computes $g=\gcd(m,n)$ and rejects a proposed primitive pair unless $F_g=1$.

With $M=40$ and exponents $3,4,5,6$, exhaustive search finds $23$ ordered solutions. Every one has a common divisor greater than $1$ and none is primitive. These finite facts demonstrate the algorithms but do not prove an unbounded conjecture.

\section{Applications and limitations}
The structural pipeline is
\[
\begin{aligned}
\text{failure of Beal}
&\Longleftrightarrow \text{existence of a primitive Beal solution}\\
&\Longrightarrow \text{a Fermat--Catalan signature}\\
&\Longrightarrow \text{a powered coprime additive triple}.
\end{aligned}
\]
If Fibonacci bases occur, the index gcd is additionally restricted to $1$ or $2$.

The pipeline standardizes bounded searches: classifying by absence of a common prime and by pairwise coprimality must agree after checking the equation. It also narrows theoretical inputs. A Fermat--Catalan strategy need address only primitive signatures in the reciprocal region, and an $abc$ strategy need address only the thin family whose three coordinates are powers of exponent at least $3$.

The unconditional conclusions are prime propagation, primitive equivalence, signature inclusion, powered-triple construction, and the Fibonacci index constraint. The two broad exclusion principles are explicit hypotheses in conditional implications. Likewise, the finite search cannot rule out remote solutions. The Fibonacci restriction leaves infinitely many index pairs and is necessary rather than sufficient.

\section{Future directions}
An effective $abc$ exclusion specialized to powered additive triples could seek an explicit bound on $\max\{x,y,z\}$ and reduce the remainder to finitely many signatures. A signature descent could exploit divisibility among exponents to organize the infinite region into minimal cases.

A complementary goal is a universal radical-defect gap: after an appropriate ordering, seek $\delta>0$ such that
\[
\rad(ABC)\leq C^{1-\delta}.
\]
Prime-support disjointness makes componentwise estimates possible for primitive candidates.

For Fibonacci bases, one may combine $\gcd(m,n)\in\{1,2\}$ with Pisano periods modulo selected primes, seeking local obstructions for each signature. Finally, one can encode base prime supports as a hypergraph. Prime propagation forbids a prime incident with exactly two of the three bases; analogous incidence constraints may be useful for equations with more summands.

\section{Conclusion}
A prime dividing two bases in $A^x+B^y=C^z$ must divide the third. This elementary law yields the exact equivalence between absence of a common prime and pairwise coprimality, so Beal's conjecture is precisely the nonexistence of primitive solutions above exponent $2$.

Every hypothetical primitive counterexample lies in the Fermat--Catalan signature region and canonically produces $(A^x,B^y,C^z)$ as a coprime additive triple with unchanged radical support. These facts isolate the conditional inputs from Fermat--Catalan and $abc$ methods that would suffice. Fibonacci bases add the condition $\gcd(m,n)\in\{1,2\}$. The final exclusion remains open, but its target is sharply organized by signatures, prime support, and arithmetic structure in the bases.

\end{document}

