from collections import defaultdict
from math import gcd
from typing import DefaultDict

def search(bound: int = 40, lo: int = 3, hi: int = 6) -> None:
    index: DefaultDict[int, list[tuple[int, int]]] = defaultdict(list)
    for c in range(1, bound + 1):
        for z in range(lo, hi + 1): index[c ** z].append((c, z))
    hits: list[tuple[int, int, int, int, int, int]] = []
    for a in range(1, bound + 1):
        for x in range(lo, hi + 1):
            for b in range(1, bound + 1):
                for y in range(lo, hi + 1):
                    for c, z in index.get(a ** x + b ** y, []):
                        hits.append((a, b, c, x, y, z))
    primitive = [t for t in hits if all(gcd(u, v) == 1 for u, v in ((t[0],t[1]),(t[0],t[2]),(t[1],t[2])))]
    print(f"ordered solutions={len(hits)}, primitive={len(primitive)}")

if __name__ == "__main__": search()

from fractions import Fraction
from math import gcd
from typing import NamedTuple

class Certificate(NamedTuple):
    exact: bool; pairwise_gcds: tuple[int,int,int]; common_gcd: int; primitive: bool; signature: Fraction

def certify(a:int,b:int,c:int,x:int,y:int,z:int) -> Certificate:
    ds=(gcd(a,b),gcd(a,c),gcd(b,c)); common=gcd(gcd(a,b),c)
    return Certificate(a**x+b**y==c**z,ds,common,ds==(1,1,1),Fraction(1,x)+Fraction(1,y)+Fraction(1,z))

if __name__ == "__main__": print(certify(7,7,14,3,4,3))

from math import gcd

def fib(n:int)->int:
    a,b=0,1
    for _ in range(n): a,b=b,a+b
    return a

def screen(m:int,n:int)->tuple[int,int,bool]:
    g=gcd(m,n); value=fib(g)
    assert gcd(fib(m),fib(n))==value
    return g,value,value==1

if __name__ == "__main__":
    for pair in [(8,15),(10,16),(12,18),(21,34)]: print(pair,screen(*pair))

